import {TownScene} from './scene.js';
import {UTILS,LABELS,VERSION,parseOSM,createTown,flows,demand,traceService,monthlyReads,exportTown,round} from './model.js';
const $=id=>document.getElementById(id),fmt=(x,d=0)=>Number(x).toLocaleString('en-CA',{maximumFractionDigits:d,minimumFractionDigits:d}),escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let town,source,scene,selected=null,asset=null,utility='electric',hour=8,scenario='normal',target=null,flow,playing=false,timer=null,fixture='actual',busy=false;
let toastTimer;
function toast(message){$('toast').textContent=message;$('toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').classList.remove('visible'),4200);}
function download(obj,name,type='application/json'){const blob=new Blob([typeof obj==='string'?obj:JSON.stringify(obj,null,2)],{type}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
const tick=()=>Math.round(hour*12);
function getState(){return {townId:town?.id,seed:town?.seed,homes:town?.count,scenario,hour,selectedPremiseId:selected?.id||null,layers:scene?.layers,validation:town?.validation};}
async function generate(seed=$('seed').value,count=Number($('size').value)){
 if(busy)throw Error('Town generation is already running.');busy=true;$('generate-btn').disabled=true;$('loading').hidden=false;await new Promise(r=>setTimeout(r,35));
 try{const start=performance.now(),next=createTown(source,{seed,count});if(!next.validation.valid)throw Error(next.validation.errors.join(', '));town=next;selected=null;asset=null;$('inspector').hidden=true;scene.load(town);$('homes-count').textContent=fmt(town.count);$('services-count').textContent=fmt(town.servicePoints.length);$('solar-count').textContent=fmt(town.premises.filter(h=>h.solar).length);$('seed').value=town.seed;$('size').value=String(town.count);$('town-title').textContent=source.label==='Imported OSM streets'?'OSM-inspired':'Whitby-inspired';$('map-title').textContent=(source.label==='Imported OSM streets'?'Imported town':'Whitby')+' / '+town.seed.split('-').at(-1);$('integrity-status').textContent='Every service connected';$('integrity-detail').textContent=`${fmt(town.validation.networkEdges)} edges · 0 orphaned services`;$('runtime-info').textContent=`v${VERSION} · ${Math.round(performance.now()-start)} ms generation & scene · ${town.source.districtTiles} district${town.source.districtTiles===1?'':'s'}`;target=town.premises.find(h=>h.occupied)?.id;updateFlow();updateScenarioNote();$('search-results').hidden=true;return getState();}
 finally{busy=false;$('generate-btn').disabled=false;$('loading').hidden=true;}
}
function updateFlow(){if(!town)return;flow=flows(town,hour,scenario==='solar'?'normal':scenario,target);scene.setFlows(flow);for(const u of UTILS){let v=flow[u].source;$("flow-"+u).textContent=u==='electric'?`${fmt(Math.abs(v),1)} kW ${v<0?'export':'import'}`:`${fmt(v,1)} m³/h supplied`;}
 const hrs=Math.floor(hour),mins=Math.round((hour-hrs)*60);$('time-label').textContent=`${String(hrs).padStart(2,'0')}:${String(mins).padStart(2,'0')}`;$('hour').value=String(tick());if(selected){const value=flow.homes.get(selected.id)[utility],el=$('inspector-body').querySelector('.big-number'),caption=$('inspector-body').querySelector('.flow-caption');if(el)el.innerHTML=`${fmt(Math.abs(value),utility==='electric'?2:3)} <small>${utility==='electric'?'kW':'m³/h'}</small>`;if(caption)caption.textContent=utility==='electric'?(value<0?'Exporting to the grid':value===0?'Supply interrupted':'Drawing from the grid'):'Flow into this property';}else if(asset)renderAsset();}
function setHour(value){if(!Number.isFinite(value)||value<0||value>=24)throw Error('Hour must be from 0 to 23.9167.');hour=Math.round(value*12)/12;updateFlow();}
function setLayer(u,on){scene.layers[u]=on;scene.setLayers(scene.layers);for(const type of UTILS){$('layer-'+type).classList.toggle('active',scene.layers[type]);$('layer-'+type).setAttribute('aria-pressed',String(scene.layers[type]));}$('map-mode').textContent=UTILS.filter(u=>scene.layers[u]).map(u=>LABELS[u]).join(' + ')||'Town landscape';}
function updateScenarioNote(){const h=town?.premises.find(h=>h.id===target);$('scenario-note').textContent={normal:'Demand changes with the hour. Solar homes can send power back upstream.',solar:'At noon, rooftop generation exceeds demand at many homes. Watch the flow reverse.',leak:`A 650 L/h leak at ${h?.id||'one home'}. Extra water demand flows through every upstream pipe.`,outage:'The substation supply is off. Grid-tied solar shuts down too; islanding is not modelled.'}[scenario];}
function setScenario(value){if(!['normal','solar','leak','outage'].includes(value))throw Error('Unknown scenario.');scenario=value;$('scenario').value=value;if(value==='solar'){setLayer('electric',true);hour=12;const h=town.premises.find(h=>h.solar&&h.occupied);if(h)selectHome(h,false);}if(value==='leak'){setLayer('water',true);utility='water';if(selected)target=selected.id;const h=town.premises.find(h=>h.id===target);if(h)selectHome(h,true);}updateFlow();if(selected)renderHome();updateScenarioNote();}
function selectHome(h,focus=false){selected=h;asset=null;fixture='actual';if(!h.services[utility])utility='electric';$('inspector').hidden=false;scene.select(h,utility,focus);renderHome();}
function line(label,value,mono=false){return `<div class="detail-line"><span>${label}</span><strong class="${mono?'mono':''}">${value}</strong></div>`;}
function sampleForHome(){let reads=monthlyReads(town,selected).filter(r=>r.commodity===utility).map(r=>({...r}));if(fixture!=='actual')reads=reads.map(r=>{if(r.direction==='export')return r;const read={...r,id:r.id+'-'+fixture,idempotencyKey:r.idempotencyKey+':'+fixture};if(fixture==='stuck'){read.registerValue=read.previousRegisterValue;read.consumption=0;read.reasonCode='SIM_STUCK_REGISTER';}if(fixture==='missing'){read.registerValue=null;read.consumption=null;read.scheduledReadAt=read.readAt;read.readAt=null;read.readType='missing';read.readStatus='missing';read.reasonCode='SIM_TELEMETRY_FAILURE';}if(fixture==='spike'){read.consumption=round(r.consumption*8);read.registerValue=round(r.previousRegisterValue+read.consumption);read.reasonCode='SIM_SPIKE';}return read;});return reads;}
function renderHome(){const h=selected,d=flow.homes.get(h.id),reads=sampleForHome(),r=reads[0],unit=utility==='electric'?'kW':'m³/h',value=d[utility],path=traceService(town,h.id,utility),dist=path.reduce((a,e)=>a+e.lengthM,0),net=town.networks[utility],tx=path.find(e=>e.kind==='transformer');const points=Array.from({length:24},(_,i)=>demand(h,i+.5,scenario==='solar'?'normal':scenario,target)[utility]);let max=Math.max(.01,...points.map(Math.abs));
 $('inspector-body').innerHTML=`<div class="eyebrow">PREMISE / ${escape(h.id)}</div><h2>${escape(h.address)}</h2><div class="address">Synthetic home · ${fmt(h.width*h.depth)} m² footprint</div><div class="home-tags"><span>${h.occupied?h.occupants+' residents':'Vacant'}</span>${h.solar?'<span>☀ '+h.solarKW+' kW solar</span>':''}${h.electricHeat?'<span>All-electric heat</span>':''}</div><button id="focus-home" class="outline-btn">Locate this home</button><div class="inspector-tabs">${UTILS.filter(u=>h.services[u]).map(u=>`<button data-utility="${u}" class="${u===utility?'active':''}">${LABELS[u]}</button>`).join('')}</div><div class="big-number ${utility}">${fmt(Math.abs(value),utility==='electric'?2:3)} <small>${unit}</small></div><div class="flow-caption">${utility==='electric'?(value<0?'Exporting to the grid':value===0?'Supply interrupted':'Drawing from the grid'):'Flow into this property'}</div><div class="spark-chart">${points.map(v=>`<span title="${fmt(v,3)} ${unit}" style="height:${Math.max(2,Math.abs(v)/max*100)}%;background:${v<0?'#cda142':utility==='water'?'#70abb0':utility==='gas'?'#ad97bf':'#8da57b'}"></span>`).join('')}</div><div class="spark-label"><span>00:00</span><span>24-hour demand profile</span><span>24:00</span></div><div class="detail-section"><h3>Connected to the source</h3><div class="chain"><div>${utility==='electric'?'Regional grid':utility==='water'?'Treated water supply':'Regional gas supply'}<small>${utility==='electric'?'69 kV incoming':'Off-map boundary'}</small></div><div>${utility==='electric'?'West substation':utility==='water'?'West pumping station':'West pressure station'}<small>${utility==='electric'?'12.47 kV distribution':utility==='water'?'10–24 in trunk → 6–16 in mains':'6 in trunk → 2–4 in mains'}</small></div><div>${utility==='electric'?'Neighbourhood transformer':'Local service connection'}<small>${utility==='electric'?'12.47 kV → 120/240 V split phase':'¾ in service pipe'}</small></div><div>${escape(r.meterId)}<small>${utility==='electric'&&h.solar?'Separate import + export registers':'AMI consumption register'}</small></div></div>${line('Source-to-meter path',fmt(dist)+' m')}${line('Service point',escape(h.services[utility]),true)}</div><div class="detail-section"><h3>June monthly read · fixture</h3><select id="fixture" aria-label="Meter reading fixture"><option value="actual">Actual reading</option><option value="stuck">Stuck register</option><option value="missing">Failed telemetry / missing read</option><option value="spike">8× consumption spike</option></select>${line('Previous register',fmt(r.previousRegisterValue,3)+' '+r.unit)}${line('Reported register',r.registerValue===null?'Missing':fmt(r.registerValue,3)+' '+r.unit)}${line('Reported consumption',r.consumption===null?'Missing':fmt(r.consumption,3)+' '+r.unit)}${reads[1]?line('Export consumption',fmt(reads[1].consumption,3)+' kWh'):''}<p class="small-note">June 1–July 1 UTC. This baseline fixture is independent of the live July scenario. Physical truth is retained separately.</p><button id="download-read" class="outline-btn">Export this read for VEE</button></div><div class="detail-section"><h3>Meter to invoice</h3><div class="pipeline"><span class="done">Read<br>fixture</span><span>VEE<br>pending</span><span>Bill<br>pending</span><span>Invoice<br>pending</span></div><p class="small-note">No VEE, bill or invoice has been processed.</p>${line('Contract account',escape(h.accountId),true)}${line('Billing cycle',String(h.billingCycle))}</div>`;
 $('fixture').value=fixture;$('fixture').onchange=e=>{fixture=e.target.value;renderHome();};$('focus-home').onclick=()=>scene.select(h,utility,true);$('download-read').onclick=()=>download({schemaVersion:'vee-input-fixture/1.0',reads:sampleForHome()},`${h.id}-${utility}-vee-fixture.json`);document.querySelectorAll('[data-utility]').forEach(btn=>btn.onclick=()=>{utility=btn.dataset.utility;fixture='actual';setLayer(utility,true);scene.select(h,utility);renderHome();});
}
function renderAsset(){const u=asset,net=town.networks[u],n=net.nodes.find(n=>n.id===net.stationId),v=flow[u].source;$('inspector-body').innerHTML=`<div class="eyebrow">SUPPLY INFRASTRUCTURE</div><h2>${escape(n.label)}</h2><div class="address">${LABELS[u]} · ${u==='electric'?'69 kV / 12.47 kV':u==='water'?'Pumped water distribution':'Regional pressure reduction'}</div><div class="big-number ${u}">${fmt(Math.abs(v),1)} <small>${net.unit==='m3/h'?'m³/h':net.unit}</small></div><div class="flow-caption">${v<0?'Returning to the regional grid':'Supplying the town'}</div><div class="detail-section">${line('Connected services',fmt(town.servicePoints.filter(s=>s.commodity===u).length))}${line('Network edges',fmt(net.edges.length))}${line('Network layout','Radial')}${u==='electric'?line('Transformers',fmt(net.nodes.filter(n=>n.kind==='transformer').length)):''}${line('Flow balance','Demand aggregated upstream')}</div><div class="detail-section"><h3>Simulation boundary</h3><p class="small-note">${u==='electric'?'A signed energy balance supports rooftop solar export. Voltage drop, phase imbalance, losses and protection coordination are not solved.':u==='water'?'Supply equals the sum of customer demand and the injected leak. Pipe diameters and burial depths are illustrative; pressure and pump head are not solved.':'Supply equals connected customer volume demand. Pipe diameters and regulation are illustrative; pressure, compressibility and gas energy conversion are not solved.'}</p></div>`;}
function closeInspector(){selected=null;asset=null;$('inspector').hidden=true;scene.clearSelection();}
function searchHomes(query){const q=query.trim().toLowerCase();if(!q)return[];return town.premises.filter(h=>h.id.toLowerCase()===q||h.id===`P-${q.padStart(5,'0')}`||h.address.toLowerCase().includes(q)).slice(0,8);}
function showSearch(){const hits=searchHomes($('search-input').value);$('search-results').hidden=false;$('search-results').innerHTML=hits.length?hits.map(h=>`<button data-home="${h.id}">${escape(h.address)}<small>${h.id}${h.solar?' · Solar home':''}</small></button>`).join(''):'<div class="empty-state">No matching homes. Try a number such as 42.</div>';document.querySelectorAll('[data-home]').forEach(b=>b.onclick=()=>{selectHome(town.premises.find(h=>h.id===b.dataset.home),true);$('search-results').hidden=true;});}
function blueprint(){
 $('blueprint-body').innerHTML=`<p class="blueprint-intro">A repeatable synthetic town built from real street geometry. The same identifiers connect the physical world, meter reads, VEE decisions, billing documents, and invoices.</p><div class="blueprint-grid"><div class="blueprint-card"><h3>Built in this version</h3><ul><li>Frozen Whitby OSM streets; import another OSM JSON extract.</li><li>20–10,000 deterministic homes, with connected utility graphs.</li><li>Substation, pumping station, gas regulator, transformers and service drops.</li><li>Signed flows, solar export, water leak and substation outage.</li><li>Separate physical truth and reported meter-read fixtures.</li></ul></div><div class="blueprint-card"><h3>Next handoff: VEE v5</h3><p>Export a town or individual read fixture. Map the normalized read contract to the actual VEE v5 schema, then return decisions using the original simulation, premise, service-point, meter and read IDs. No private VEE endpoint or source code was supplied.</p></div></div><h3 class="blueprint-subtitle">One identity chain</h3><table class="boundary-table"><thead><tr><th>Entity</th><th>Purpose</th></tr></thead><tbody><tr><td>Building → premise</td><td>Physical place and selectable house</td></tr><tr><td>Service point → installation</td><td>Commodity, active service and read schedule</td></tr><tr><td>Meter → register → read</td><td>Device identity, units, cumulative measurement</td></tr><tr><td>Account → contract → tariff assignment</td><td>Customer ownership and future charging rules</td></tr><tr><td>VEE → billing document → invoice</td><td>Future processing results, attached by stable IDs</td></tr></tbody></table><h3 class="blueprint-subtitle">What “repeatable” means</h3><p class="small-note">The source snapshot, generator version, seed and home count determine the town. Fixed five-minute time steps determine live demand. Export captures the source fingerprint, projection and scale, network graph and sample reads. Regeneration never uses live OSM data.</p><h3 class="blueprint-subtitle">Model limits</h3><p class="small-note">This is an operational simulator prototype. Flow is demand aggregated through radial networks. Pressure, voltage, losses, water hammer, gas compressibility and capacity constraints are not solved. Pipe sizes and transformer ratings are illustrative. The map’s coloured underground layers are surface overlays. Monthly reads are fixture data; there are no calculated charges, VEE judgements, billing documents or invoices. Town configuration lives in this browser session; JSON exports preserve generated data. 10,000-home generation is tested, but browser frame rate has not been measured.</p><div class="blueprint-actions"><a href="./REQUIREMENTS.md" download>Requirements & handoff</a><a href="./DATA-CONTRACT.schema.json" download>JSON Schema</a></div><p class="small-note">Road geometry: <a href="https://www.openstreetmap.org/copyright" target="_blank" rel="noopener">OpenStreetMap contributors (ODbL)</a>. Utilities and buildings are fictional. Physics adapter references: <a href="https://www.epa.gov/water-research/epanet" target="_blank" rel="noopener">EPANET</a> and <a href="https://opendss.epri.com/PowerFlow.html" target="_blank" rel="noopener">EPRI OpenDSS</a>.</p>`;$('blueprint').showModal();
}
function wire(){
 for(const u of UTILS)$("layer-"+u).onclick=()=>setLayer(u,!scene.layers[u]);$('show-services').onchange=e=>scene.setXray(e.target.checked);$('hour').oninput=e=>setHour(Number(e.target.value)/12);$('scenario').onchange=e=>setScenario(e.target.value);$('generate-btn').onclick=()=>generate().then(()=>toast('Town regenerated. Every service is connected.')).catch(e=>toast(e.message));$('seed').onkeydown=e=>{if(e.key==='Enter')$('generate-btn').click();};$('reset-seed').onclick=()=>{$('seed').value='WHITBY-042';};$('home-view').onclick=()=>scene.home();$('top-view').onclick=()=>scene.top();$('zoom-in').onclick=()=>scene.zoom(.75);$('zoom-out').onclick=()=>scene.zoom(1.3);$('close-inspector').onclick=closeInspector;$('search-form').onsubmit=e=>{e.preventDefault();showSearch();};$('search-input').oninput=()=>{if($('search-input').value.length>0)showSearch();else $('search-results').hidden=true;};$('search-input').onkeydown=e=>{if(e.key==='Escape')$('search-results').hidden=true;};
 $('play-btn').onclick=()=>{playing=!playing;$('play-btn').textContent=playing?'Ⅱ':'▶';$('play-btn').setAttribute('aria-label',playing?'Pause the day':'Play the day');$('tick-status').textContent=playing?'1 day / 72 seconds':'Paused';if(timer)clearInterval(timer);if(playing)timer=setInterval(()=>{if(!busy)setHour(((tick()+1)%288)/12);},250);};
 $('requirements-btn').onclick=blueprint;$('limits-btn').onclick=blueprint;$('close-blueprint').onclick=()=>$('blueprint').close();$('export-btn').onclick=async()=>{$('export-btn').disabled=true;toast('Preparing the town and meter-read fixtures…');await new Promise(r=>setTimeout(r,30));try{download(exportTown(town),`${town.id}-${town.count}-homes.json`);toast('Town export ready. Includes model and monthly read fixtures.');}catch(e){toast('Export failed: '+e.message);}finally{$('export-btn').disabled=false;}};
 $('import-btn').onclick=()=>$('osm-file').click();$('osm-file').onchange=async e=>{const file=e.target.files[0];if(!file)return;let old=source;try{if(file.size>20*1024*1024)throw Error('Choose an OSM JSON file smaller than 20 MB.');const raw=JSON.parse(await file.text());source=parseOSM(raw);await generate();toast(`Imported roads. ${source.omittedNodes} disconnected boundary nodes excluded.`);}catch(e){source=old;toast(e.message);}finally{$('osm-file').value='';}};
 document.addEventListener('keydown',e=>{if(e.key==='Escape'){closeInspector();$('search-results').hidden=true;}});
}
function registerTools(){const ctx=document.modelContext;if(!ctx?.registerTool)return;const tools=[{name:'read_town_state',description:'Read the current synthetic town, active scenario, utility layers and selected premise.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:()=>getState()},{name:'select_town_premise',description:'Select and focus a premise in the 3D town.',inputSchema:{type:'object',properties:{premiseId:{type:'string'}},required:['premiseId'],additionalProperties:false},annotations:{readOnlyHint:false},execute:input=>{const h=town.premises.find(h=>h.id===input?.premiseId);if(!h)throw Error('Premise not found.');selectHome(h,true);return getState();}},{name:'set_town_scenario',description:'Set the current live simulation scenario and update visible flows. Does not run VEE or billing.',inputSchema:{type:'object',properties:{scenario:{type:'string',enum:['normal','solar','leak','outage']}},required:['scenario'],additionalProperties:false},annotations:{readOnlyHint:false},execute:input=>{setScenario(input?.scenario);return getState();}}];for(const t of tools)try{Promise.resolve(ctx.registerTool(t)).catch(()=>{});}catch{}}
try{const response=await fetch('./whitby-roads.json');if(!response.ok)throw Error('Street data could not be loaded. Reload to try again.');source=parseOSM(await response.json());scene=new TownScene($('map'),({home,asset:u})=>{if(home)selectHome(home);else if(u){asset=u;selected=null;scene.clearSelection();$('inspector').hidden=false;renderAsset();}});scene.play=!matchMedia('(prefers-reduced-motion: reduce)').matches;wire();await generate();registerTools();}
catch(e){console.error(e);$('loading').hidden=false;$('loading').innerHTML=`<div class="error-state"><strong>The town could not open.</strong><p>${escape(e.message)}</p><p>This 3D view needs a browser with WebGL enabled.</p><button onclick="location.reload()">Try again</button></div>`;}
